- How would you extend to return the actual segmentations list as well as the count?

## Why This Is Asked

This question probes understanding of sorting trade-offs (in-place memory vs stability vs constants) and how hybrid approaches balance speed, especially relevant in finance and large-scale data.

## Key Concepts

- 3-way partitioning in quicksort
- Insertion sort for small slices
- In-place sorting and O(1) extra space
- Average vs worst-case complexities; pivot choice

## Code Example

```javascript
function sortHybrid(a){
  const TH = 16;
  const swap=(i,j)=>{ [a[i],a[j]]=[a[j],a[i]]; };
  const insertSort=(l,r)=>{
    for(let i=l+1;i<=r;i++){
      let x=a[i], j=i-1;
      while(j>=l && a[j]>x){ a[j+1]=a[j]; j--; }
      a[j+1]=x;
    }
  };
  const partition=(lo,hi)=>{
    const p=a[lo+((hi-lo)>>1)];
    let i=lo, lt=lo, gt=hi;
    while(i<=gt){
      if(a[i]<p){ swap(i,lt); i++; lt++; }
      else if(a[i]>p){ swap(i,gt); gt--; }
      else i++;
    }
    return [lt,gt];
  };
  const qs=(lo,hi)=>{
    if(lo>=hi) return;
    if(hi-lo+1 <= TH){ insertSort(lo,hi); return; }
    const [l,r] = partition(lo,hi);
    qs(lo, l-1);
    qs(r+1, hi);
  };
  qs(0,a.length-1);
}
```

## Why This Is Asked

This question adds counting of optimal partitions to a standard min-max DP, testing both correctness and edge-case handling in a realistic workload-balancing scenario.

## Key Concepts

- DP with a value-cost pair (minCost, count) and prefix sums for O(1) subarray sums
- Top-down memoization and bottom-up tabulation with identical transitions
- Edge-case handling: n<k invalid, zeros, large sums

## Code Example

```javascript
function minCostPartitions(nums, k){
  const n = nums.length;
  const pref = new Array(n+1).fill(0);
  for(let i=0;i<n;i++) pref[i+1]=pref[i]+nums[i];
  const dp = Array.from({length:n+1},()=>Array.from({length:k+1},()=>null));
  for(let i=1;i<=n;i++) dp[i][1] = {best: pref[i], count:1};
  for(let i=1;i<=n;i++){
    for(let j=2;j<=Math.min(i,k);j++){
      let best = Infinity, cnt = 0;
      for(let t=j-1;t<=i-1;t++){
        const last = pref[i]-pref[t];
        const prev = dp[t][j-1];
        if(!prev) continue;
        const cand = Math.max(prev.best, last);
        if(cand < best){ best = cand; cnt = prev.count; }
        else if(cand === best){ cnt += prev.count; }
      }
      dp[i][j] = {best, count: cnt};
    }
  }
  const res = dp[n][k];
  return res ? {cost: res.best, ways: res.count} : null;
}
```

## Follow-up Questions

- How would you modify to return all partition indices achieving the min cost?
- Could you optimize to O(nk) time with a narrowed search if nums are non-decreasing?

## Why This Is Asked

Tests algorithmic depth and practical handling of worst-case quicksort behavior.

## Key Concepts

- Introsort: hybrid of quicksort and heapsort with depth guard
- Median-of-three pivot to avoid pathological inputs
- In-place partition and recursion depth management
- Complexity: O(n log n) average and worst-case; O(log n) stack space

## Code Example

```javascript
// Introsort skeleton in JS
function introsort(arr) {
  const n = arr.length;
  if (n <= 1) return;
  const maxDepth = Math.floor(2 * Math.log2(n));
  function swap(i, j) { const t = arr[i]; arr[i] = arr[j]; arr[j] = t; }
  function medianOfThree(lo, mid, hi) {
    if (arr[lo] > arr[mid]) swap(lo, mid);
    if (arr[lo] > arr[hi]) swap(lo, hi);
    if (arr[mid] > arr[hi]) swap(mid, hi);
    return mid;
  }
  function partition(lo, hi) {
    const mid = Math.floor((lo + hi) / 2);
    const m = medianOfThree(lo, mid, hi);
    swap(m, hi);
    const pivot = arr[hi];
    let i = lo;
    for (let j = lo; j < hi; j++) {
      if (arr[j] <= pivot) { swap(i, j); i++; }
    }
    swap(i, hi);
    return i;
  }
  function heapSort(lo, hi) {
    const n = hi - lo + 1;
    function heapify(i, size) {
      while (true) {
        const l = 2 * i + 1;
        const r = l + 1;
        let largest = i;
        if (l < size && arr[lo + l] > arr[lo + largest]) largest = l;
        if (r < size && arr[lo + r] > arr[lo + largest]) largest = r;
        if (largest !== i) { swap(lo + i, lo + largest); i = largest; } else break;
      }
    }
    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) heapify(i, n);
    for (let end = n - 1; end > 0; end--) {
      swap(lo, lo + end);
      heapify(0, end);
    }
  }
  function insertionSort(lo, hi) {
    for (let i = lo + 1; i <= hi; i++) {
      const key = arr[i];
      let j = i - 1;
      while (j >= lo && arr[j] > key) { arr[j + 1] = arr[j]; j--; }
      arr[j + 1] = key;
    }
  }
  function quickSort(lo, hi, depth) {
    const size = hi - lo + 1;
    if (size <= 16) { insertionSort(lo, hi); return; }
    if (depth <= 0) { heapSort(lo, hi); return; }
    const p = partition(lo, hi);
    quickSort(lo, p - 1, depth - 1);
    quickSort(p + 1, hi, depth - 1);
  }
  quickSort(0, n - 1, maxDepth);
}
```

## Follow-up Questions
- How would you adapt this to sort objects by a numeric key while preserving comparator locality?
- Compare cache behavior of introsort vs pure mergesort on large datasets.

## Why This Is Asked
Explores a practical, augmented Trie approach blending prefix queries with order-statistics, a gap in typical BST/trie questions.

## Key Concepts
- Trie augmentation with endCount and subCount
- Duplicates handled via endCount
- Lexicographic kthWord via endCount before children

## Code Example
```javascript
class Node {
  constructor() {
    this.next = new Map();
    this.end = 0;
    this.sub = 0;
  }
}
class Trie {
  constructor(){ this.root = new Node(); }
  insert(w){ let cur=this.root; cur.sub++; for(const ch of w){ if(!cur.next.has(ch)) cur.next.set(ch,new Node()); cur=cur.next.get(ch); cur.sub++; } cur.end++; }
  delete(w){ let cur=this.root; cur.sub--; for(const ch of w){ cur=cur.next.get(ch); cur.sub--; } cur.end--; }
  countPrefix(p){ let cur=this.root; for(const ch of p){ if(!cur.next.has(ch)) return 0; cur=cur.next.get(ch); } return cur.sub; }
  kthWord(k){ let res=''; let node=this.root; while(true){ if(k <= node.end) return res; k -= node.end; // skip words ending here
      // iterate in lexical order
      const keys = Array.from(node.next.keys()).sort();
      for(const ch of keys){ const child=node.next.get(ch); if(child.sub >= k){ res += ch; node = child; break; } else k -= child.sub; }
    }
  }
}
```

## Follow-up Questions
- How would you adapt for Unicode or larger alphabets?
- What are memory implications for dense vs sparse alphabets?
- How would you support delete of non-existent words without errors?

## Why This Is Asked

This question evaluates dynamic programming skills with state expansion, requiring candidates to track whether the cell removal has been used. It tests proper handling of grid boundary conditions and provides opportunities to discuss space optimization strategies and compare memoization versus tabulation approaches.

## Key Concepts
- DP with auxiliary state tracking
- Space optimization using rolling arrays
- Boundary condition handling
- State transition logic

## Code Example
```javascript
function minPathWithOneRemoval(grid) {
  const m = grid.length, n = grid[0].length;
  const dp0 = Array(m).fill().map(() => Array(n).fill(Infinity));
  const dp1 = Array(m).fill().map(() => Array(n).fill(Infinity));

  dp0[0][0] = grid[0][0];
  dp1[0][0] = 0;

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i > 0) {
        dp0[i][j] = Math.min(dp0[i][j], grid[i][j] + dp0[i-1][j]);
        dp1[i][j] = Math.min(dp1[i][j], grid[i][j] + dp1[i-1][j]);
        dp1[i][j] = Math.min(dp1[i][j], dp0[i-1][j]);
      }
      if (j > 0) {
        dp0[i][j] = Math.min(dp0[i][j], grid[i][j] + dp0[i][j-1]);
        dp1[i][j] = Math.min(dp1[i][j], grid[i][j] + dp1[i][j-1]);
        dp1[i][j] = Math.min(dp1[i][j], dp0[i][j-1]);
      }
    }
  }

  return Math.min(dp0[m-1][n-1], dp1[m-1][n-1]);
}
```

## Time/Space Complexity
- Time: O(m × n) - we process each cell once
- Space: O(m × n) - can be optimized to O(n) using rolling arrays since we only need the previous row

## Why This Is Asked

Tests practical algorithm design that blends classic sorts and data-structure choices. It assesses the ability to identify run structures, select appropriate sorting strategies by run size, and implement an efficient, stable k-way merge.

## Key Concepts

- Natural monotone runs detection in O(n)
- Insertion sort for small ranges; mergesort for larger ranges
- K-way merge with a min-heap and lazy advancement
- Stability guarantees and complexity trade-offs

## Code Example

```javascript
function hybridSort(a){
  const n=a.length; 
  // 1) detect monotone runs
  const runs=[]; let i=0;
  while(i<n){
    let j=i+1;
    while(j<n && a[j-1] <= a[j]) j++;
    runs.push([i,j]);
    i=j;
  }
  // 2) sort each run
  for(const [l,r] of runs){
    if(r-l <= 32) insertionSort(a,l,r);
    else mergeSort(a,l,r);
  }
  // 3) k-way merge using a min-heap
  const heap=new MinHeap((x,y)=> x.val<y.val);
  for(let idx=0; idx<runs.length; idx++){
    const [l,r]=runs[idx];
    if(l<r) heap.push({val:a[l], pos:l, runIdx:idx});
  }
  const out=new Array(n); let k=0;
  while(!heap.isEmpty()){
    const {val,pos,runIdx}=heap.pop();
    out[k++]=val;
    const [l,r]=runs[runIdx];
    const next=pos+1;
    if(next<r) heap.push({val:a[next], pos:next, runIdx});
  }
  for(let t=0;t<n;t++) a[t]=out[t];
}

function insertionSort(a,l,r){
  for(let i=l+1;i<r;i++){
    const key=a[i]; let j=i-1;
    while(j>=l && a[j]>key){ a[j+1]=a[j]; j--; }
    a[j+1]=key;
  }
}

function mergeSort(a,l,r){
  if(r-l<=1) return;
  const m=(l+r)>>1;
  mergeSort(a,l,m); mergeSort(a,m,r);
  // merge [l,m) and [m,r)
  const left=a.slice(l,m); let i=0, j=m, t=l;
  while(i<left.length && j<r) a[t++]= left[i++]<a[j]? left[i-1]: a[j++];
  while(i<left.length) a[t++]=left[i++];
  while(j<r) a[t++]=a[j++];
}

class MinHeap{
  constructor(cmp){ this.a=[]; this.cmp=cmp||((x,y)=> x<y); }
  push(x){ this.a.push(x); this.bubbleUp(this.a.length-1); }
  pop(){ if(this.a.length===0) return null; const top=this.a[0]; const end=this.a.pop(); if(this.a.length){ this.a[0]=end; this.sinkDown(0); } return top; }
  isEmpty(){ return this.a.length===0; }
  bubbleUp(n){ const a=this.a[n]; while(n>0){ const p=(n-1)>>1; if(this.cmp(a, this.a[p])){ this.a[n]=this.a[p]; n=p; } else break; } this.a[n]=a; }
  sinkDown(n){ const length=this.a.length; const element=this.a[n]; while(true){ let child2=(n+1)*2, child1=child2-1; let swap=null; if(child1<length){ if(this.cmp(this.a[child1], element)) swap=child1; } if(child2<length){ if(this.cmp(this.a[child2], swap===null?element:this.a[child1])) swap=child2; } if(swap===null) break; this.a[n]=this.a[swap]; n=swap; } this.a[n]=element; }
}
```

